package main

import (
	"context"
	"log/slog"
	"os"
)

func main() {
	// JSON handler -> one machine-parseable record per line.
	base := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
		Level: slog.LevelInfo, // Debug lines are skipped and never formatted
	}))
	// With() returns a child logger that stamps these fields on every line.
	log := base.With("service", "checkout")

	ctx := context.Background()
	log.Debug("loading config") // below LevelInfo -> suppressed
	log.InfoContext(ctx, "order placed", "order_id", 42, "amount", 19.99)
}
// Output:
// {"time":"...","level":"INFO","msg":"order placed","service":"checkout","order_id":42,"amount":19.99}

var (
	reqs = promauto.NewCounterVec(prometheus.CounterOpts{
		Name: "http_requests_total",
	}, []string{"route", "code"})
	inFlight = promauto.NewGauge(prometheus.GaugeOpts{
		Name: "http_in_flight_requests",
	})
	dur = promauto.NewHistogramVec(prometheus.HistogramOpts{
		Name:    "http_request_duration_seconds",
		Buckets: prometheus.DefBuckets,
	}, []string{"route"})
)

func instrument(route string, code int, elapsed time.Duration) {
	inFlight.Inc()
	defer inFlight.Dec()
	reqs.WithLabelValues(route, strconv.Itoa(code)).Inc() // Counter: up only
	dur.WithLabelValues(route).Observe(elapsed.Seconds())  // Histogram: buckets
}

// Expose everything for Prometheus to scrape.
func serve() { http.Handle("/metrics", promhttp.Handler()) }

var tracer = otel.Tracer("checkout")

func handleOrder(ctx context.Context, id string) error {
	// Start returns a NEW ctx carrying the active span; thread it downstream.
	ctx, span := tracer.Start(ctx, "handleOrder",
		trace.WithAttributes(attribute.String("order.id", id)))
	defer span.End()

	if err := queryDB(ctx); err != nil { // child span nests under this one
		span.RecordError(err)
		span.SetStatus(codes.Error, err.Error())
		return err
	}
	return nil
}

func queryDB(ctx context.Context) error {
	_, span := tracer.Start(ctx, "db.query") // shares the parent's trace_id
	defer span.End()
	return nil
}

// A slog handler that stamps the active trace_id on every record.
type TraceHandler struct{ slog.Handler }

func (h TraceHandler) Handle(ctx context.Context, r slog.Record) error {
	if sc := trace.SpanContextFromContext(ctx); sc.IsValid() {
		r.AddAttrs(slog.String("trace_id", sc.TraceID().String()))
	}
	return h.Handler.Handle(ctx, r)
}

func example(ctx context.Context) {
	log := slog.New(TraceHandler{slog.NewJSONHandler(os.Stdout, nil)})
	ctx, span := tracer.Start(ctx, "GET /orders")
	defer span.End()
	// InfoContext forwards ctx, so the handler can pull the trace_id.
	log.InfoContext(ctx, "order placed", "order_id", 42)
}
// Output: {...,"msg":"order placed","order_id":42,"trace_id":"4bf92f3577b34da6a3ce929d0e0e4736"}

var (
	// RED: Rate + Errors via one CounterVec (code label yields error rate),
	// Duration via a HistogramVec. Labels use the BOUNDED route template.
	reqs = promauto.NewCounterVec(prometheus.CounterOpts{
		Name: "http_requests_total",
	}, []string{"route", "code"}) // GOOD: /users/:id, not /users/8123
	dur = promauto.NewHistogramVec(prometheus.HistogramOpts{
		Name: "http_request_duration_seconds", Buckets: prometheus.DefBuckets,
	}, []string{"route"})
)

func recordRED(routeTemplate string, code int, elapsed time.Duration) {
	// BAD: prometheus label "user_id" or raw r.URL.Path -> millions of series.
	// GOOD: bounded route template keeps cardinality finite.
	reqs.WithLabelValues(routeTemplate, strconv.Itoa(code)).Inc()
	dur.WithLabelValues(routeTemplate).Observe(elapsed.Seconds())
}
// PromQL error rate: rate(http_requests_total{code=~"5.."}[5m]) / rate(http_requests_total[5m])

