import (
	"context"
	"log/slog"
	"os"
)

func main() {
	// Strip the volatile time attr so output is deterministic for the demo.
	opts := &slog.HandlerOptions{
		Level: slog.LevelInfo, // Debug lines below this are skipped (and not formatted)
		ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {
			if a.Key == slog.TimeKey {
				return slog.Attr{} // drop the timestamp
			}
			return a
		},
	}
	// JSON handler -> one structured record per line.
	base := slog.New(slog.NewJSONHandler(os.Stdout, opts))

	// With() returns a child logger that stamps these fields on every line.
	log := base.With("service", "checkout")

	ctx := context.Background()
	log.Debug("loading config")                       // below LevelInfo -> suppressed
	log.InfoContext(ctx, "order placed", "order_id", 42, "amount", 19.99)
	log.WarnContext(ctx, "inventory low", "sku", "A1", "left", 3)
}

