package solution

import (
	"sync"
	"time"
)

// countKey is the bounded composite label set (route + status code).
type countKey struct {
	route string
	code  int
}

// Recorder is an in-memory RED-metrics recorder (no external deps).
type Recorder struct {
	mu        sync.Mutex                  // guards all maps for concurrent Observe
	counts    map[countKey]int            // requests per (route, code)
	errors    map[string]int              // 5xx responses per route
	durations map[string]time.Duration    // accumulated latency per route
}

func NewRecorder() *Recorder {
	return &Recorder{
		counts:    make(map[countKey]int),
		errors:    make(map[string]int),
		durations: make(map[string]time.Duration),
	}
}

// Observe records one completed request (the RED method).
func (r *Recorder) Observe(route string, code int, dur time.Duration) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.counts[countKey{route, code}]++ // Rate: total requests by route+code
	if code >= 500 {                  // Errors: only server errors
		r.errors[route]++
	}
	r.durations[route] += dur // Duration: accumulate latency per route
}

func (r *Recorder) Count(route string, code int) int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.counts[countKey{route, code}]
}

func (r *Recorder) Errors(route string) int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.errors[route]
}

func (r *Recorder) TotalDuration(route string) time.Duration {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.durations[route]
}

