package solution

import (
	"sync"
	"testing"
	"time"
)

func TestRecorder(t *testing.T) {
	r := NewRecorder()
	r.Observe("/orders", 200, 10*time.Millisecond)
	r.Observe("/orders", 200, 20*time.Millisecond)
	r.Observe("/orders", 500, 30*time.Millisecond)
	r.Observe("/cart", 503, 5*time.Millisecond)

	if got := r.Count("/orders", 200); got != 2 {
		t.Errorf("Count(/orders,200)=%d want 2", got)
	}
	if got := r.Count("/orders", 500); got != 1 {
		t.Errorf("Count(/orders,500)=%d want 1", got)
	}
	if got := r.Errors("/orders"); got != 1 {
		t.Errorf("Errors(/orders)=%d want 1", got)
	}
	if got := r.Errors("/cart"); got != 1 {
		t.Errorf("Errors(/cart)=%d want 1", got)
	}
	if got := r.TotalDuration("/orders"); got != 60*time.Millisecond {
		t.Errorf("TotalDuration(/orders)=%v want 60ms", got)
	}
}

func TestRecorderConcurrent(t *testing.T) {
	r := NewRecorder()
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			r.Observe("/x", 200, time.Millisecond)
		}()
	}
	wg.Wait()
	if got := r.Count("/x", 200); got != 100 {
		t.Errorf("Count(/x,200)=%d want 100", got)
	}
}

