package obs

import (
	"context"
	"log/slog"

	"go.opentelemetry.io/otel/trace"
)

// TraceHandler wraps a slog.Handler and stamps trace_id on every record.
type TraceHandler struct {
	slog.Handler // embedded: inherits Enabled, WithAttrs, WithGroup
}

// Handle adds the active trace_id (if any) then delegates.
func (h TraceHandler) Handle(ctx context.Context, r slog.Record) error {
	if sc := trace.SpanContextFromContext(ctx); sc.IsValid() {
		r.AddAttrs(slog.String("trace_id", sc.TraceID().String()))
	}
	return h.Handler.Handle(ctx, r)
}

// NewTraceLogger builds a logger whose every line is trace-correlated.
func NewTraceLogger(inner slog.Handler) *slog.Logger {
	return slog.New(TraceHandler{Handler: inner})
}

package obs

import (
	"context"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
	"golang.org/x/sync/errgroup"
)

var tracer = otel.Tracer("fanout")

// FanOut runs fn for each item concurrently, each under its own child span
// nested in the caller's trace. It blocks until all goroutines finish, so
// the caller's span (and ctx) outlive every child.
func FanOut[T any](ctx context.Context, spanName string, items []T, fn func(context.Context, T) error) error {
	// errgroup derives a ctx that is cancelled on the first error and its
	// Wait() is the barrier that keeps the parent alive until children end.
	g, gctx := errgroup.WithContext(ctx)
	for _, item := range items {
		item := item // capture per iteration (pre-1.22 safety)
		g.Go(func() error {
			// Start a CHILD span from gctx, which carries the parent span,
			// so this span shares the parent's trace_id instead of orphaning.
			childCtx, span := tracer.Start(gctx, spanName,
				trace.WithSpanKind(trace.SpanKindInternal))
			defer span.End()
			if err := fn(childCtx, item); err != nil {
				// Record on THIS child span, not the parent.
				span.RecordError(err)
				span.SetStatus(codes.Error, err.Error())
				span.SetAttributes(attribute.Bool("fanout.failed", true))
				return err
			}
			return nil
		})
	}
	return g.Wait() // barrier: parent must not End its span until this returns
}
